edits.anchor:
if not absolute_path.exists():
    raise PatchForgeError(
        f"{context}: file does not exist: {relative_path}"
    )

edits.content:
action = file_spec.get(
    "action",
    "modify",
)

if not isinstance(action, str):
    raise PatchForgeError(
        f"{context}: action must be a string."
    )

if action not in (
    "modify",
    "create",
):
    raise PatchForgeError(
        f"{context}: unsupported file action '{action}'."
    )

if action == "create":
    if absolute_path.exists():
        raise PatchForgeError(
            f"{context}: create target already exists: "
            f"{relative_path}"
        )

    if "sha256" in file_spec:
        raise PatchForgeError(
            f"{context}: create entries must not contain sha256."
        )

    if "edits" in file_spec:
        raise PatchForgeError(
            f"{context}: create entries use content instead of edits."
        )

    content = normalize_newlines(
        require_string(
            file_spec,
            "content",
            context,
        )
    )

    new_bytes = content.encode(
        "utf-8"
    )

    prepared.append(
        PreparedFile(
            relative_path=relative_path,
            absolute_path=absolute_path,
            original_exists=False,
            original_bytes=b"",
            new_bytes=new_bytes,
            original_sha256="",
            new_sha256=sha256_bytes(
                new_bytes
            ),
        )
    )

    continue

edits.old:
for item in files:
    destination = (
        backup_root
        / Path(item.relative_path)
    )

    destination.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    destination.write_bytes(
        item.original_bytes
    )

    manifest_files.append(
        {
            "path": item.relative_path,
            "sha256": item.original_sha256,
            "patched_sha256": item.new_sha256,
        }
    )

edits.new:
for item in files:
    if item.original_exists:
        destination = (
            backup_root
            / Path(item.relative_path)
        )

        destination.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

        destination.write_bytes(
            item.original_bytes
        )

    manifest_files.append(
        {
            "path": item.relative_path,
            "existed": item.original_exists,
            "sha256": (
                item.original_sha256
                if item.original_exists
                else None
            ),
            "patched_sha256": item.new_sha256,
        }
    )

edits.old:
for item in reversed(written):
    try:
        atomic_write(
            item.absolute_path,
            item.original_bytes,
        )
    except Exception:
        pass

edits.new:
for item in reversed(written):
    try:
        if item.original_exists:
            atomic_write(
                item.absolute_path,
                item.original_bytes,
            )
        else:
            item.absolute_path.unlink(
                missing_ok=True
            )
    except Exception:
        pass

if item.original_exists:
    print(
        f"  old SHA-256: "
        f"{item.original_sha256}"
    )
else:
    print(
        "  old SHA-256: (new file)"
    )

print(
    f"  new SHA-256: "
    f"{item.new_sha256}"
)

edits.old:
    backup = (
        checkpoint
        / "files"
        / relative
    )

    destination = resolve_repo_path(
        repo,
        relative,
    )

    if not backup.exists():
        raise PatchForgeError(
            f"Missing checkpoint file: {relative}"
        )

    restore_items.append(
        (
            destination,
            backup.read_bytes(),
        )
    )

for destination, data in restore_items:
    atomic_write(
        destination,
        data,
    )

edits.new:
    destination = resolve_repo_path(
        repo,
        relative,
    )

    existed = entry.get(
        "existed",
        True,
    )

    if not isinstance(existed, bool):
        raise PatchForgeError(
            "Checkpoint manifest contains invalid existed state."
        )

    if existed:
        backup = (
            checkpoint
            / "files"
            / relative
        )

        if not backup.exists():
            raise PatchForgeError(
                f"Missing checkpoint file: {relative}"
            )

        restore_items.append(
            (
                destination,
                backup.read_bytes(),
            )
        )
    else:
        patched_hash = entry.get(
            "patched_sha256"
        )

        if destination.exists():
            if not destination.is_file():
                raise PatchForgeError(
                    f"Cannot remove created path during rollback: "
                    f"{relative}"
                )

            if isinstance(patched_hash, str):
                current_hash = sha256_bytes(
                    destination.read_bytes()
                )

                if current_hash.lower() != patched_hash.lower():
                    raise PatchForgeError(
                        f"Created file changed after patch; "
                        f"refusing to delete it during rollback: "
                        f"{relative}"
                    )

        restore_items.append(
            (
                destination,
                None,
            )
        )

for destination, data in restore_items:
    if data is None:
        destination.unlink(
            missing_ok=True
        )
    else:
        atomic_write(
            destination,
            data,
        )
